def iso3_to_iso2(iso3):
    code = str(iso3).upper().strip()

    # Kosovo는 ISO 3166 공식 alpha-3 코드가 없어
    # 대시보드에서는 널리 쓰이는 사용자 지정 코드 XKX를 사용합니다.
    # FlagCDN에서는 Kosovo를 xk로 제공하므로 별도 처리합니다.
    if code == "XKX":
        return "xk"

    try:
        item = pycountry.countries.get(alpha_3=code)
        return item.alpha_2.lower() if item else None
    except Exception:
        return None


def get_flag_url(iso3):
    iso2 = iso3_to_iso2(iso3)
    return f"https://flagcdn.com/w40/{iso2}.png" if iso2 else ""


def flag_html(iso3, css_class):
    url = get_flag_url(iso3)
    if not url:
        return ""
    return f'<img src="{url}" class="{css_class}" alt="{iso3}">'


def get_country_year(country, year):
    temp = df[
        (df[COL["country"]] == country)
        & (df[COL["year"]] == year)
    ]
    return None if temp.empty else temp.iloc[0]


def number_format(value, digits=1):
    return "-" if pd.isna(value) else f"{float(value):.{digits}f}"


def money_format(value):
    if pd.isna(value):
        return "-"

    value = float(value)

    if abs(value) >= 1_000_000_000_000:
        return f"${value / 1_000_000_000_000:.2f} T"
    if abs(value) >= 1_000_000_000:
        return f"${value / 1_000_000_000:.1f} B"
    if abs(value) >= 1_000_000:
        return f"${value / 1_000_000:.1f} M"

    return f"${value:,.0f}"


def percent_change(current, previous):
    if (
        previous is None
        or pd.isna(previous)
        or pd.isna(current)
        or previous == 0
    ):
        return None

    return (current - previous) / abs(previous) * 100


def delta_html(delta, unit="%", increase_bad=False):
    if delta is None or pd.isna(delta):
        return '<div class="delta-neutral">이전 값 없음</div>'

    up = delta >= 0
    arrow = "▲" if up else "▼"

    if increase_bad:
        css = "delta-negative" if up else "delta-positive"
    else:
        css = "delta-positive" if up else "delta-negative"

    return (
        f'<div class="{css}">'
        f'{arrow} {abs(delta):.1f}{unit}'
        '</div>'
    )


def ranking_value_format(metric, value):
    if pd.isna(value):
        return "-"

    if metric in ["GDP", "군사비"]:
        return money_format(value)

    if metric in ["군사비/GDP", "TIV 수입 점유율"]:
        return f"{value:.2f}%"

    return f"{value:.1f}"


