def bubble_size(values):
    v = np.sqrt(
        np.clip(
            values.astype(float),
            0,
            None,
        )
    )

    lo = np.nanmin(v)
    hi = np.nanmax(v)

    if hi == lo:
        return np.full(
            len(v),
            (
                BUBBLE_MIN
                + BUBBLE_MAX
            ) / 2,
        )

    return (
        BUBBLE_MIN
        + (v - lo)
        / (hi - lo)
        * (
            BUBBLE_MAX
            - BUBBLE_MIN
        )
    )

SIM_TOP_N = 5

CORR_VARS = [
    ("GDP", "gdp_calculated", True),
    ("군사비", "current_usd", True),
    ("군사비/GDP", X_COL, False),
    ("TIV 수입 점유율", "TIV_5Y_Share", True),
    ("분쟁 위험도", "human_hazard_score", False),
]


def similarity_axes(d, metric):
    """버블차트 화면에 보이는 좌표(로그축 반영)를 그대로 거리 계산에 사용"""
    m = PAGE2_METRIC[metric]

    fx = np.log10(d[X_COL].clip(lower=0.01))

    if m["log_y"]:
        fy = np.log10(d[m["col"]].clip(lower=0.004))
    else:
        fy = d[m["col"]].astype(float)

    return fx, fy


def find_similar_countries(
    data,
    year,
    metric,
    iso,
    top_n=SIM_TOP_N,
):
    """
    유사도 정의
    ------------------------------------------------
    1) 비교 축 3개
       - log10(GDP 대비 군사비) : 버블차트 x축
       - 기준지표                : 버블차트 y축
                                  (TIV는 log10)
       - log10(GDP)             : 국가 체급
         * 버블 크기 라디오와 무관하게 GDP 고정
    2) 각 축을 그 해 전체 국가 기준 z-표준화
       -> 단위가 다른 축을 같은 저울에 올림
       -> 거리 1 = 표준편차 1개만큼 떨어짐
    3) 표준화 유클리드 거리 d 계산
    4) 축 개수로 정규화 : d / sqrt(축 개수)
       -> 축 하나당 평균 거리로 환산
       -> 축을 몇 개 쓰든 눈금이 같아짐
    5) 유사도 = 100 * exp(-정규화 거리)
       -> 거리 0이면 100, 멀수록 지수적으로 감쇠
       -> 절대 기준이라 국가·연도 간 비교 가능
       -> 지수 감쇠는 표시용 변환이며
          순위는 거리 d 그대로임
    """
    m = PAGE2_METRIC[metric]
    other = "tiv" if metric == "risk" else "risk"
    o = PAGE2_METRIC[other]

    need = [X_COL, m["col"], SIZE_COL]

    d = data[data["Year"] == year].dropna(
        subset=need
    )
    d = d[
        (d[X_COL] > 0)
        & (d[SIZE_COL] > 0)
    ].copy()

    if d.empty or iso not in set(d["Iso3"]):
        return None, other

    fx, fy = similarity_axes(d, metric)
    fz = np.log10(d[SIZE_COL])

    axes = []

    for f in (fx, fy, fz):
        sd = f.std(ddof=0) or 1.0
        axes.append((f - f.mean()) / sd)

    pos = d.index[d["Iso3"] == iso][0]
    base = [a.loc[pos] for a in axes]

    d["_dist"] = np.sqrt(
        sum(
            (a - b) ** 2
            for a, b in zip(axes, base)
        )
    )

    d["유사도"] = 100 * np.exp(
        -d["_dist"] / np.sqrt(len(axes))
    )

    out = (
        d[d["Iso3"] != iso]
        .nsmallest(top_n, "_dist")
        .copy()
    )

    out.insert(0, "순위", range(1, len(out) + 1))

    cols = [
        "순위",
        "Country",
        "Iso3",
        "유사도",
        "_dist",
        X_COL,
        m["col"],
        o["col"],
    ]

    return out[cols], other


def make_corr_heatmap(
    data,
    year,
    method="spearman",
    height=430,
):
    d = data[data["Year"] == year]

    frame = {}
    labels = []

    for label, col, is_skewed in CORR_VARS:
        if col not in d.columns:
            continue

        s = pd.to_numeric(d[col], errors="coerce")

        if s.notna().sum() < 10:
            continue

        if method == "pearson" and is_skewed:
            s = np.log10(s.where(s > 0))
            label = f"{label} (로그)"

        frame[label] = s
        labels.append(label)

    if len(labels) < 2:
        return empty_figure(
            f"{year}년에는 상관분석에 쓸 지표가 부족합니다.",
            height=height,
        ), 0

    mat = pd.DataFrame(frame)
    n = int(mat.dropna().shape[0])
    corr = mat.corr(method=method).loc[labels, labels]

    fig = go.Figure(
        go.Heatmap(
            z=corr.values,
            x=labels,
            y=labels,
            zmin=-1,
            zmax=1,
            zmid=0,
            colorscale=CORR_SCALE,
            text=np.round(corr.values, 2),
            texttemplate="%{text:.2f}",
            textfont=dict(size=11),
            hovertemplate=(
                "%{y} ↔ %{x}<br>"
                "상관계수 %{z:.2f}"
                "<extra></extra>"
            ),
            colorbar=dict(
                thickness=12,
                len=0.8,
                tickvals=[-1, -0.5, 0, 0.5, 1],
            ),
        )
    )

    fig.update_yaxes(
        autorange="reversed",
        fixedrange=True,
        automargin=True,
        tickfont=dict(size=11),
    )

    fig.update_xaxes(
        fixedrange=True,
        automargin=True,
        tickangle=-18,
        side="bottom",
        tickfont=dict(size=10),
    )

    fig.update_layout(
        title=dict(
            text=(
                f"{year}년 지표 간 상관관계 "
                f"({'스피어만' if method == 'spearman' else '피어슨'}"
                f", n={n})"
            ),
            x=0.02,
            xanchor="left",
            font=dict(size=14, color=NAVY_DEEP),
        ),
        height=height,
        dragmode=False,
        margin=dict(l=62, r=48, t=48, b=62),
        template="plotly_white",
        font=dict(
            family="Malgun Gothic, AppleGothic, NanumGothic, sans-serif",
            size=12,
        ),
        hovermode="closest",
    )

    return fig, n

def make_bubble(
    data,
    year,
    metric="risk",
    size_col=SIZE_COL,
    highlight=None,
    similar=None,
):
    m = PAGE2_METRIC[metric]

    if (
        metric == "risk"
        and
        year < RISK_START
    ):
        return empty_figure(
            f"분쟁위험도(INFORM)는 "
            f"{RISK_START}년부터 제공됩니다.<br>"
            f"{RISK_START}년 이후를 선택하거나 "
            "TIV 차트를 이용하세요."
        )

    d = data[
        data["Year"] == year
    ].dropna(
        subset=[
            X_COL,
            m["col"],
            size_col,
        ]
    )

    d = d[
        (d[X_COL] > 0)
        &
        (d[size_col] > 0)
    ]

    if d.empty:
        return empty_figure(
            f"{year}년 데이터가 없습니다."
        )

    y = (
        d[m["col"]]
        .clip(lower=0.004)
        if m["log_y"]
        else d[m["col"]]
    )

    if m["log_color"]:
        cvals = np.log10(
            d[m["col"]]
            .clip(lower=0.004)
        )

        color_ticks = [
            0.004,
            0.01,
            0.1,
            1,
            10,
        ]

        colorbar = dict(
            title=dict(
                text=m["label"],
                side="right",
            ),
            thickness=12,
            len=0.75,
            tickvals=np.log10(
                color_ticks
            ),
            ticktext=[
                "0",
                "0.01",
                "0.1",
                "1",
                "10",
            ],
        )

    else:
        cvals = d[m["col"]]

        colorbar = dict(
            title=dict(
                text=m["label"],
                side="right",
            ),
            thickness=12,
            len=0.75,
        )
    sim_set = set(similar or [])

    fig = go.Figure(
        go.Scatter(
            x=d[X_COL],
            y=y,
            mode="markers",
            customdata=np.stack(
                [
                    d["Country"],
                    d["Iso3"],
                    d[SIZE_COL],
                    d[MILEX_COL],
                    d[m["col"]],
                ],
                axis=-1,
            ),
            hovertemplate=(
                "<b>%{customdata[0]}</b><br>"
                "GDP 대비 군사비 "
                "%{x:.2f}%<br>"
                + m["label"]
                + " %{customdata[4]:"
                + m["fmt"]
                + "}<br>"
                "GDP "
                "%{customdata[2]:,.0f}<br>"
                "군사비 "
                "%{customdata[3]:,.0f}"
                "<extra></extra>"
            ),
            marker=dict(
                size=bubble_size(
                    d[size_col]
                ),
                sizemode="diameter",
                color=cvals,
                colorscale=m["scale"],
                showscale=True,
                colorbar=colorbar,
                opacity=(
                    0.72
                    if highlight is None
                    else [
                        1.0
                        if iso == highlight
                        else (
                            0.85
                            if iso in sim_set
                            else 0.18
                        )
                        for iso in d["Iso3"]
                    ]
                ),
                line=dict(
                    width=[
                        3.0
                        if iso == highlight
                        else (
                            2.2
                            if iso in sim_set
                            else 0.5
                        )
                        for iso in d["Iso3"]
                    ],
                    color=[
                        RED
                        if iso == highlight
                        else (
                            SIM_EDGE
                            if iso in sim_set
                            else "rgba(60,60,60,0.35)"
                        )
                        for iso in d["Iso3"]
                    ],
                ),
            ),
            selected=dict(
                marker=dict(
                    opacity=0.95
                )
            ),
            unselected=dict(
                marker=dict(
                    opacity=0.25
                )
            ),
        )
    )

    fig.update_layout(
        title=dict(
            text=(
                f"{year}년 · "
                "GDP 대비 군사비 × "
                f"{m['label']} "
                f"(n={len(d)})"
            ),
            font=dict(size=15, color=NAVY_DEEP),
        ),
        xaxis=dict(
            title="GDP 대비 군사비 (%)",
            type="log",
            fixedrange=True,
            tickvals=[
                0.2,
                0.5,
                1,
                2,
                5,
                10,
                20,
                40,
            ],
            ticktext=[
                "0.2",
                "0.5",
                "1",
                "2",
                "5",
                "10",
                "20",
                "40",
            ],
        ),
        yaxis=dict(
            title=m["label"],
            fixedrange=True,
            type=(
                "log"
                if m["log_y"]
                else "linear"
            ),
            tickvals=m["yticks"],
            ticktext=m["ytext"],
        ),
        height=460,
        dragmode=False,
        **BASE_LAYOUT,
    )

    return fig


def make_page2_line(
    data,
    iso,
    metric="risk",
):
    m = PAGE2_METRIC[metric]

    d = data[
        data["Iso3"] == iso
    ].sort_values("Year")

    if d.empty:
        return empty_figure(
            "국가를 선택하세요."
        )

    name = d[
        "Country"
    ].iloc[0]

    full = pd.DataFrame(
        {
            "Year":
                range(
                    YEAR_MIN,
                    YEAR_MAX + 1,
                )
        }
    )

    d = full.merge(
        d,
        on="Year",
        how="left",
    )

    fig = make_subplots(
        specs=[
            [
                {
                    "secondary_y":
                        True
                }
            ]
        ]
    )

    fig.add_trace(
        go.Scatter(
            x=d["Year"],
            y=d[MILEX_COL],
            name="군사비",
            mode="lines+markers",
            connectgaps=False,
            line=dict(
                color=MILEX_COLOR,
                width=2,
            ),
            marker=dict(size=4),
            hovertemplate=(
                "%{x}년<br>"
                "군사비 "
                "%{y:,.0f}"
                "<extra></extra>"
            ),
        ),
        secondary_y=False,
    )

    fig.add_trace(
        go.Scatter(
            x=d["Year"],
            y=d[m["col"]],
            name=m["label"],
            mode="lines+markers",
            connectgaps=False,
            line=dict(
                color=m["color"],
                width=2,
                dash="dot",
            ),
            marker=dict(size=4),
            hovertemplate=(
                "%{x}년<br>"
                + m["label"]
                + " %{y:"
                + m["fmt"]
                + "}"
                "<extra></extra>"
            ),
        ),
        secondary_y=True,
    )

    if metric == "risk":
        fig.add_vrect(
            x0=YEAR_MIN - 0.5,
            x1=RISK_START - 0.5,
            fillcolor="#000000",
            opacity=0.05,
            line_width=0,
        )

        fig.add_annotation(
            x=(
                YEAR_MIN
                + RISK_START
            ) / 2,
            y=1.0,
            yref="paper",
            text=(
                "위험도 미제공 "
                f"(~{RISK_START - 1})"
            ),
            showarrow=False,
            font=dict(
                size=10,
                color="#7A8794",
            ),
        )

    fig.update_xaxes(
        title_text="연도",
        dtick=2,
        fixedrange=True,
        range=[
            YEAR_MIN - 0.5,
            YEAR_MAX + 0.5,
        ],
    )

    fig.update_yaxes(
        title_text="군사비",
        color=MILEX_COLOR,
        secondary_y=False,
        rangemode="tozero",
        fixedrange=True,
    )

    fig.update_yaxes(
        title_text=m["label"],
        color=m["color"],
        secondary_y=True,
        showgrid=False,
        tickformat=m["fmt"],
        fixedrange=True,
    )

    fig.update_layout(
        title=dict(
            text=f"{name} · 연도별 추이",
            font=dict(size=15),
            y=0.97,
            yanchor="top",
        ),
        legend=dict(
            orientation="h",
            y=1.02,
            x=0,
            yanchor="bottom",
        ),
        height=460,
        margin=dict(
            l=60,
            r=70,
            t=85,
            b=55,
        ),
        template="plotly_white",
        font=dict(
            family=(
                "Malgun Gothic, "
                "AppleGothic, "
                "NanumGothic, "
                "sans-serif"
            ),
            size=12,
        ),
        hovermode="closest",
        dragmode=False,
    )

    return fig


